 app.querySelectorAll('.it input').forEach(function(x){x.onchange=function(){var ix=Number(x.closest('.it').getAttribute('data-i'));tick(ix,x.checked);};});}
function tick(ix,done){var by=who();if(!by){render();return;}var it=D.ck[ix];BUSY[ix]=1;it.done=done;render();
 fetch('/webhook/cbs-task-act',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({a:'tick',t:D.t,i:ix,text:it.t,done:done,by:by})})
 .then(function(r){if(!r.ok)throw 0;return r.json();}).then(function(res){delete BUSY[ix];if(res.checklist)D.ck=res.checklist;render(res.ok?'':(res.message||'Not saved. Try again.'));})
 .catch(function(){delete BUSY[ix];it.done=!done;render('Not saved. Check your signal and tap again.');});}
