/* CBS task checklists: admin save + crew link (from the programme page), crew ticks (from the crew page). */
const h=this.helpers,H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
const S=v=>v==null?'':String(v).trim();const jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();const num=v=>Number(v)||0;
const b=$input.first().json.body||{};const a=S(b.a),by=S(b.by).slice(0,80);
const R=(ok,x)=>[{json:Object.assign({ok:ok},x||{})}];
const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
const stamp=now.slice(8,10)+'/'+now.slice(5,7)+'/'+now.slice(0,4)+' '+now.slice(11,16);
const list=async t=>{const L=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t='+t,body:{},json:true,timeout:20000});return (Array.isArray(L)?L:[]).filter(r=>r&&r.id!=null);};
const save=(t,id,row)=>h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t='+t+'&id='+id+'&k='+K+'&partial=1',body:row,json:true,timeout:20000});
const ckl=r=>{try{const x=JSON.parse(S(r.checklist_json)||'[]');return Array.isArray(x)?x.filter(i=>i&&S(i.t)).map(i=>({t:S(i.t).slice(0,200),done:!!i.done,by:S(i.by).slice(0,80),at:S(i.at).slice(0,16)})):[];}catch(e){return [];}};
const statusFor=(ck,old)=>{if(!ck.length)return S(old)||'Not started';const d=ck.filter(i=>i.done).length;return d===ck.length?'Done':(d>0||S(old)==='In progress'?'In progress':'Not started');};
const KD=k=>{k=S(k);return k==='task'||k==='sub'?k:'phase';};
const tok=()=>(Date.now().toString(36)+Math.random().toString(36).slice(2,10)+Math.random().toString(36).slice(2,10)).slice(0,26);
const items=await list('progitems');
if(a==='tick'){
 const t=S(b.t);if(t.length<16)return R(false,{message:'This link is not valid.'});
 if(!by)return R(false,{message:'Enter your name.'});
 const r=items.find(x=>S(x.check_token)===t);if(!r)return R(false,{message:'This task is no longer on the programme.'});
 const ck=ckl(r);const i=num(b.i);if(i<0||i>=ck.length||ck[i].t!==S(b.text).slice(0,200))return R(false,{message:'The checklist has changed. Refresh the page.',checklist:ck});
 const done=b.done===true||b.done==='true';ck[i].done=done;ck[i].by=done?by:'';ck[i].at=done?now:'';
 const st=statusFor(ck,r.status);
 await save('progitems',r.id,{checklist_json:JSON.stringify(ck),status:st,updated_by:by,updated_at:now});
 return R(true,{checklist:ck,status:st});
}
const job=S(b.job).replace(/[^0-9A-Za-z-]/g,'');
if(!job)return R(false,{message:'No job number.'});if(!by)return R(false,{message:'Enter your name.'});
const r=items.find(x=>String(x.id)===S(b.id)&&jk(x.job_no)===jk(job));
if(!r)return R(false,{message:'That task was not found. Refresh the page.'});
if(items.some(x=>KD(x.kind)!=='phase'&&S(x.parent_id)===String(r.id)))return R(false,{message:'This has items under it. Add the checklist to those instead.'});
const progs=(await list('programmes')).filter(p=>jk(p.job_no)===jk(job)).sort((x,y)=>num(y.id)-num(x.id));const prog=progs[0];
const histLine=async line=>{if(prog)await save('programmes',prog.id,{history:[S(prog.history),stamp+' - '+line].filter(Boolean).join(String.fromCharCode(10))});};
if(a==='link'){
 let t=S(r.check_token);if(t.length<16){t=tok();await save('progitems',r.id,{check_token:t});await histLine('Crew checklist link made for '+S(r.name)+' by '+by);}
 return R(true,{token:t,url:H+'cbs-task?t='+t});
}
if(a==='save'){
 const old=ckl(r);const inc=(Array.isArray(b.items)?b.items:[]).slice(0,60).map(i=>({t:S(i&&i.t).slice(0,200),done:!!(i&&i.done)})).filter(i=>i.t);
 const ck=inc.map((i,ix)=>{const o=old.find(x=>x.t===i.t)||null;if(i.done&&o&&o.done)return {t:i.t,done:true,by:o.by,at:o.at};return {t:i.t,done:i.done,by:i.done?by:'',at:i.done?now:''};});
 const row={checklist_json:JSON.stringify(ck),updated_by:by,updated_at:now};
 if(!ck.length&&b.pct!==undefined){const p=S(b.pct);row.pct=p===''?null:Math.max(0,Math.min(100,Math.round(Number(p)||0)));}
 if(ck.length){row.status=statusFor(ck,r.status);row.pct=null;}
 await save('progitems',r.id,row);
 const d=ck.filter(i=>i.done).length;
 await histLine('Checklist for '+S(r.name)+' saved by '+by+(ck.length?' ('+d+' of '+ck.length+' done)':(row.pct!=null?' ('+row.pct+'% complete)':'')));
 return R(true,{checklist:ck,status:row.status||S(r.status)});
}
return R(false,{message:'Unknown action.'});

