function deco(){var pg=(window.D.p||{}).programme;if(!pg||(pg.status!=='Open'&&pg.status!=='Draft'))return;
 app.querySelectorAll('[data-id]').forEach(function(el){var r=find(el.getAttribute('data-id'));if(!r||!leaf(r))return;
  var b=el.querySelector(':scope > .b');
  if(b){if(b.querySelector('.ckb'))return;var x=document.createElement('button');x.type='button';x.className='btn ghost sm ckb';x.textContent=lab(r);x.onclick=function(ev){ev.stopPropagation();openDlg(r);};b.insertBefore(x,b.children[1]||null);return;}
  if(el.classList.contains('gl')&&!el.querySelector('.ckg')){var g=document.createElement('button');g.type='button';g.className='gib ckg';g.title='Checklist';g.textContent='\u2611'+(r.ck_total?' '+(r.ck_done||0)+'/'+r.ck_total:'');g.onclick=function(ev){ev.stopPropagation();openDlg(r);};var mb=el.querySelector('[data-a=menu]');el.insertBefore(g,mb||null);}});}
