function openDlg(r){
 var L=(r.checklist||[]).map(function(i){return {t:s(i.t),done:!!i.done,by:s(i.by),at:s(i.at),saved:true};}),orig=JSON.stringify(L.map(function(i){return [i.t,i.done];})),pct=r.ck_total?'':(r.pct||'');
