 function close(force){if(!force&&dirty()&&!confirm('Close without saving your changes?'))return;o.remove();}
 o.addEventListener('click',function(ev){if(ev.target===o)close();});
 function draw(msg){var d=L.filter(function(i){return i.done;}).length,p=L.length?Math.round(100*d/L.length):0;
