  h+='<div class="ckl"><b>Crew link</b><div id="ckLk">'+(r.check_token?'<code>'+e(location.origin+'/webhook/cbs-task?t='+r.check_token)+'</code><button type="button" class="btn ghost sm" id="ckCp">Copy link</button>':'<div class="m">Opens this one task\u2019s checklist and nothing else. Paste it into the ServiceM8 job.</div><button type="button" class="btn ghost sm" id="ckGl" style="margin-top:6px">Get crew link</button>')+'</div></div>';
